@startuml
class Library {
}
class RegisteredUser {
  +securityDeposit : float
  +phone : string
  +email : string
  +mail : string
}
class BorrowableItem {
  +libraryCode : string
  +location : string
}
class Book extends BorrowableItem {
  +publisher : string
}
class MagazineIssue extends BorrowableItem {
  +publicationDate : date
  +publisher : string
}
class MusicCD extends BorrowableItem {
  +publisher : string
  +artist : string
}
class Film extends BorrowableItem {
  +duration : int
  +publisher : string
}
class VHSFilm extends Film {}
class DVDFilm extends Film {}

Library "1" -- "*" RegisteredUser : has
Library "1" -- "*" BorrowableItem : has
RegisteredUser "0..1" -- "0..3" BorrowableItem : borrows
Book "1..*" -- "1..*" BorrowableItem : has authors
Film "1..*" -- "1..*" BorrowableItem : has actors
@enduml

